#pragma once

#include <stddef.h>
#include <zmk/behavior.h>

/**
 * @brief Accessors used by the Studio "tapdances" RPC subsystem (see
 *        app/src/studio/tap_dance_subsystem.c) to enumerate and edit the tap-dance behaviors
 *        configured on the device, without exposing the internal
 *        `struct behavior_tap_dance_config` layout from behavior_tap_dance.c.
 *
 * The per-instance config/bindings storage generated by the devicetree macros in
 * behavior_tap_dance.c is already mutable RAM (non-const statics), and it is the exact storage
 * the runtime reads on every press, so edits via the setters below take effect immediately.
 * The number of taps (bindings length) is fixed by the devicetree; adding/removing whole
 * tap-dance instances or changing the tap count is out of scope, and nothing is persisted
 * across reboots yet (mirroring the combos subsystem's current milestones).
 */

/** @brief Number of tap-dance instances configured in the devicetree. */
size_t zmk_tap_dances_get_count(void);

/**
 * @return The behavior device name for the tap-dance at `index` (its DT label property if set,
 *         otherwise the node name), or NULL if `index` is out of range.
 */
const char *zmk_tap_dances_get_name(size_t index);

/** @return The tapping term in ms, or -EINVAL if `index` is out of range. */
int32_t zmk_tap_dances_get_tapping_term_ms(size_t index);

/**
 * @brief Get a pointer to the bindings array (one entry per tap count) for the tap-dance at
 *        `index`, along with its length.
 * @return Pointer to the bindings, with `*len_out` set to the number of entries. NULL (with
 *         `*len_out` set to 0) if `index` is out of range.
 */
const struct zmk_behavior_binding *zmk_tap_dances_get_bindings(size_t index, size_t *len_out);

/**
 * @brief Update an existing tap-dance's tapping term. Takes effect immediately.
 * @return 0 on success, -EINVAL if `index` is out of range.
 */
int zmk_tap_dances_set_tapping_term_ms(size_t index, uint32_t tapping_term_ms);

/**
 * @brief Replace the binding invoked for tap count `binding_index + 1`. Takes effect
 *        immediately. `binding.behavior_dev` must remain valid for the lifetime of the device
 *        (pass a name returned by zmk_behavior_find_behavior_name_from_local_id()).
 * @return 0 on success, -EINVAL if `index` is out of range, -ERANGE if `binding_index` is out
 *         of range for this tap-dance.
 */
int zmk_tap_dances_set_binding(size_t index, size_t binding_index,
                               struct zmk_behavior_binding binding);

/**
 * @brief Delete every persisted tap-dance edit and restore the live configs to the stock
 *        (devicetree) values, in place. Used by the Studio "Restore Stock Settings" RPC.
 * @return 0 on success.
 */
int zmk_tap_dances_reset_settings(void);
